// ❌ 10,000 listeners, re-attached on every re-render
function renderRowsBad(rows) {
  list.innerHTML = '';
  for (const row of rows) {
    const el = document.createElement('div');
    el.className = 'row';
    el.textContent = row.title;
    el.addEventListener('click', () => select(row.id));   // one closure per row
    list.appendChild(el);
  }
}

// ✅ One listener, works for rows added tomorrow
list.addEventListener('click', (event) => {
  const row = event.target.closest('.row');       // survives clicks on inner spans/icons
  if (!row || !list.contains(row)) return;        // ignore clicks outside our rows
  select(row.dataset.id);
});

function renderRows(rows) {
  list.innerHTML = rows
    .map((r) => '<div class="row" data-id="' + r.id + '">' + r.title + '</div>')
    .join('');
  // no listeners to re-attach — the container handler already covers everything
}

// Capture phase: intercept before descendants (e.g., analytics, preventing a handler)
modal.addEventListener(
  'keydown',
  (e) => {
    if (e.key === 'Escape') close();
    if (trap.has(e.key)) e.stopPropagation();     // stop inner handlers seeing it
  },
  { capture: true }
);

// Non-bubbling events: use their bubbling variants for delegation
input.addEventListener('focusin', onIn);          // 'focus' doesn't bubble
